<?php
$siteName=$settings['site_name']??'Taharat Agro';
$invoicePaid=$order['payment_status']==='paid'?(float)$order['grand_total']:(!empty($order['delivery_charge_paid_at'])?(float)$order['delivery_charge']:0);
